static pthread_once_t once = PTHREAD_ONCE_INIT;
static config_t *cfg;                       /* published by pthread_once */

static void build(void) { cfg = config_load(); }

const config_t *config(void) {
    pthread_once(&once, build);              /* exactly once, ordered */
    return cfg;                              /* lock-free fast path */
}

