static once_flag flag = ONCE_FLAG_INIT;
static config_t *cfg;

static void build(void) { cfg = config_load(); }

const config_t *config(void) {
    call_once(&flag, build);                 /* C11 <threads.h> */
    return cfg;
}

static _Atomic(config_t *) cfg;
static mtx_t init_lock;

const config_t *config(void) {
    config_t *c = atomic_load_explicit(&cfg, memory_order_acquire);
    if (!c) {
        mtx_lock(&init_lock);
        c = atomic_load_explicit(&cfg, memory_order_relaxed);
        if (!c) {
            c = config_load();
            atomic_store_explicit(&cfg, c, memory_order_release);
        }
        mtx_unlock(&init_lock);
    }
    return c;
}
